Object.assign(chinese,{'Phụ kho có nhân viên chưa có trong danh sách':'支援倉庫紀錄含員工名單中不存在的人員','Báo công đã xác nhận thiếu ngày sản lượng':'已確認報工缺少產量日期'});
export function translateToolbar(value: string, locale: string): string {
 const reverse: Record<string,string> = reverseIndex ?? (reverseIndex = {...Object.fromEntries(Object.entries(english).map(([vi,en])=>[en,vi])), ...Object.fromEntries(Object.entries(chinese).map(([vi,zh])=>[zh,vi])), '搜尋欄位':'TRA THEO','搜尋內容':'NỘI DUNG TRA','清除':'Xóa lọc','變更紀錄':'Nhật ký thay đổi','新增臨時生產工單':'Thêm lệnh phát sinh','新增生產工單':'Tạo thêm LSX'});
 if(locale==='vi'&&value.trim()==='Chờ xác nhận hoàn thành')return value.replace('Chờ xác nhận hoàn thành','Chờ xác nhận HT');
 const shortStatus:Record<string,string>={'Đang sản xuất':'Đang SX','Chưa sản xuất':'Chưa SX','Hoàn thành sản xuất':'Hoàn thành SX'};
 if(locale==='vi'&&shortStatus[value.trim()])return value.replace(value.trim(),shortStatus[value.trim()]);
 const raw=value.trim(), prefix=value.slice(0,value.indexOf(raw));
 const translated=locale==='zh'?chinese[reverse[raw]||raw] : locale==='en'?english[reverse[raw]||raw] : reverse[raw];
 if(translated)return prefix+translated+value.slice(value.indexOf(raw)+raw.length);
 // Preserve leading icons and dynamic counts; never translate enum values/keys.
 const match=/^([＋+✎⌕✓↶←◷⇩▤↻⊘⌫×↑↳👤▦▣⌘◫⚙\s]*)(.*?)(\s*\(\d+\))?$/.exec(raw);
 if(match){const base=reverse[match[2]]||match[2];const label=locale==='zh'?chinese[base]:locale==='en'?english[base]:base;if(label)return prefix+match[1]+label+(match[3]||'');}
 return value;
}
export const toolbarLocale=(): ToolbarLocale => typeof document==='undefined'?'vi':document.documentElement.lang.startsWith('zh')?'zh':document.documentElement.lang==='en'?'en':'vi';
export function subscribeToolbarLocale(notify:()=>void) { window.addEventListener('onspa-language',notify); return ()=>window.removeEventListener('onspa-language',notify); }

